# Cluster settings: the one place that names an account or a path on the cluster.
# Sourced on the cluster by torch/generated/<run_id>/submit.sh, torch/submit_pack.sh and
# torch/submit_setup_env.sh; nothing else in the repository holds a personal value.
#
# To change a setting, do not edit this file. Either
#   - export the variable before the command:   BM_ACCOUNT=my_account bash torch/generated/<run_id>/submit.sh
#   - or keep your own values in torch/.env, one KEY=value per line, no quotes. Git ignores that
#     file and Mutagen syncs it to the cluster, so it stays yours.
# An exported variable wins over torch/.env, which wins over the default below.
#
#   BM_ACCOUNT      Slurm account to charge                      default: your Slurm default account
#   BM_SCRATCH      datasets, features, checkpoints, logs, runs  default: /scratch/$USER/cv_project_runs
#   BM_REPO         the Mutagen-synced checkout on the cluster   default: the checkout this file is in
#   BM_HF_HOME      Hugging Face cache and token                 default: /scratch/$USER/hf_cache
#   BM_CONDA_SH     conda's activation script                    default: /scratch/$USER/miniconda3/etc/profile.d/conda.sh
#   BM_CONDA_ENV    the environment every job activates          default: /scratch/$USER/miniconda3/envs/cvmem
#   BM_SBATCH_ARGS  extra sbatch options for every job, such as  default: none
#                   --partition=... --qos=... --constraint=...
#   BM_GPU_TYPE     GPU model for the tasks that need a GPU       default: any GPU
#                   (l40s, a100, ...; becomes --gres=gpu:<type>:1)
#   BM_GPU_SBATCH_ARGS  extra sbatch options for GPU tasks only   default: none
#   BM_PACK_CPUS, BM_PACK_MEM, BM_PACK_TIME   size of the one-job  default: 8, 64G, 08:00:00
#                   GPU run of torch/submit_pack.sh
#   BM_PARALLEL     tasks running at once in that job             default: 3

_bm_torch=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
if [ -f "$_bm_torch/.env" ]; then
    while IFS='=' read -r _bm_key _bm_value || [ -n "$_bm_key" ]; do
        _bm_key=${_bm_key#export }
        case "$_bm_key" in ''|'#'*|*[!A-Za-z0-9_]*) continue ;; esac
        [ -n "${!_bm_key:-}" ] || export "$_bm_key=$_bm_value"
    done < "$_bm_torch/.env"
fi
export BM_ACCOUNT="${BM_ACCOUNT:-}"
export BM_SCRATCH="${BM_SCRATCH:-/scratch/$USER/cv_project_runs}"
export BM_REPO="${BM_REPO:-$(dirname "$_bm_torch")}"
export BM_HF_HOME="${BM_HF_HOME:-/scratch/$USER/hf_cache}"
export BM_CONDA_SH="${BM_CONDA_SH:-/scratch/$USER/miniconda3/etc/profile.d/conda.sh}"
export BM_CONDA_ENV="${BM_CONDA_ENV:-/scratch/$USER/miniconda3/envs/cvmem}"
export BM_SBATCH_ARGS="${BM_SBATCH_ARGS:-}"
export BM_GPU_TYPE="${BM_GPU_TYPE:-}"
export BM_GPU_SBATCH_ARGS="${BM_GPU_SBATCH_ARGS:-}"
export BM_PACK_CPUS="${BM_PACK_CPUS:-8}" BM_PACK_MEM="${BM_PACK_MEM:-64G}" BM_PACK_TIME="${BM_PACK_TIME:-08:00:00}"
export BM_PARALLEL="${BM_PARALLEL:-3}"
export HF_HOME="$BM_HF_HOME"
unset _bm_torch _bm_key _bm_value
